#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

// =====================================================
// LEFT BTS7960
// =====================================================

#define LEFT_R_EN   27
#define LEFT_L_EN   14
#define LEFT_RPWM   25
#define LEFT_LPWM   26

// =====================================================
// RIGHT BTS7960
// =====================================================

#define RIGHT_R_EN  33
#define RIGHT_L_EN  32
#define RIGHT_RPWM  18
#define RIGHT_LPWM  19

// =====================================================
// SPEED / PWM
// =====================================================

#define PWM_FREQ 20000
#define PWM_RES  8

// =====================================================
// SAFETY
// =====================================================

// Stop the motors if communication is lost
// for more than 5 seconds.

#define COMMUNICATION_TIMEOUT 5000

unsigned long lastCommandTime = 0;

// =====================================================
// CONTROLLER ADDRESS
// =====================================================

uint8_t controllerAddress[6];

bool controllerFound = false;

// =====================================================
// COMMAND PACKET
// =====================================================

struct CommandPacket {
  char command;
  uint8_t speed;
};

// =====================================================
// STOP MOTORS
// =====================================================

void stopMotors() {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, 0);
  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// FORWARD
// =====================================================

void forward(uint8_t speed) {
  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// REVERSE
// =====================================================

void reverse(uint8_t speed) {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}

// =====================================================
// TURN LEFT
// =====================================================

void turnLeft(uint8_t speed) {
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// TURN RIGHT
// =====================================================

void turnRight(uint8_t speed) {
  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}

// =====================================================
// ADD CONTROLLER
// =====================================================

bool addController() {

  if (esp_now_is_peer_exist(controllerAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};

  memcpy(
    peerInfo.peer_addr,
    controllerAddress,
    6
  );

  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  if (
    esp_now_add_peer(&peerInfo) != ESP_OK
  ) {

    Serial.println("Could not add controller");

    return false;
  }

  return true;
}

// =====================================================
// RECEIVE DATA
// =====================================================

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {

  // ---------------------------------------------------
  // CONTROLLER DISCOVERY
  // ---------------------------------------------------

  if (
    len >= 5 &&
    memcmp(data, "HELLO", 5) == 0
  ) {

    memcpy(
      controllerAddress,
      info->src_addr,
      6
    );

    controllerFound = addController();

    if (controllerFound) {

      Serial.println();
      Serial.println("================================");
      Serial.println("CONTROLLER FOUND!");
      Serial.println("================================");

      const char reply[] = "CAR";

      esp_now_send(
        controllerAddress,
        (uint8_t *)reply,
        sizeof(reply)
      );
    }

    return;
  }

  // ---------------------------------------------------
  // IGNORE COMMANDS IF NO CONTROLLER
  // ---------------------------------------------------

  if (!controllerFound) {
    return;
  }

  // ---------------------------------------------------
  // CHECK PACKET SIZE
  // ---------------------------------------------------

  if (
    len != sizeof(CommandPacket)
  ) {

    Serial.println("Invalid command packet");

    return;
  }

  // ---------------------------------------------------
  // READ COMMAND
  // ---------------------------------------------------

  CommandPacket packet;

  memcpy(
    &packet,
    data,
    sizeof(packet)
  );

  // Reset communication timer
  lastCommandTime = millis();

  // ---------------------------------------------------
  // EXECUTE COMMAND
  // ---------------------------------------------------

  switch (packet.command) {

    case 'F':

      forward(packet.speed);

      Serial.print("FORWARD  Speed: ");
      Serial.println(packet.speed);

      break;

    case 'B':

      reverse(packet.speed);

      Serial.print("REVERSE  Speed: ");
      Serial.println(packet.speed);

      break;

    case 'L':

      turnLeft(packet.speed);

      Serial.print("LEFT  Speed: ");
      Serial.println(packet.speed);

      break;

    case 'R':

      turnRight(packet.speed);

      Serial.print("RIGHT  Speed: ");
      Serial.println(packet.speed);

      break;

    case 'S':

      stopMotors();

      Serial.println("STOP");

      break;

    default:

      stopMotors();

      Serial.println("UNKNOWN COMMAND");

      break;
  }
}

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  // ---------------------------------------------------
  // MOTOR DRIVER ENABLE PINS
  // ---------------------------------------------------

  pinMode(
    LEFT_R_EN,
    OUTPUT
  );

  pinMode(
    LEFT_L_EN,
    OUTPUT
  );

  pinMode(
    RIGHT_R_EN,
    OUTPUT
  );

  pinMode(
    RIGHT_L_EN,
    OUTPUT
  );

  // Enable both BTS7960 drivers

  digitalWrite(
    LEFT_R_EN,
    HIGH
  );

  digitalWrite(
    LEFT_L_EN,
    HIGH
  );

  digitalWrite(
    RIGHT_R_EN,
    HIGH
  );

  digitalWrite(
    RIGHT_L_EN,
    HIGH
  );

  // ---------------------------------------------------
  // PWM
  // ---------------------------------------------------

  ledcAttach(
    LEFT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    LEFT_LPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_LPWM,
    PWM_FREQ,
    PWM_RES
  );

  // Make absolutely sure motors start stopped

  stopMotors();

  // ---------------------------------------------------
  // WI-FI / ESP-NOW
  // ---------------------------------------------------

  WiFi.mode(WIFI_STA);

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );

  Serial.println();
  Serial.println("================================");
  Serial.println("ESP32 CAR");
  Serial.println("================================");

  Serial.print("Car MAC: ");
  Serial.println(
    WiFi.macAddress()
  );

  // ---------------------------------------------------
  // START ESP-NOW
  // ---------------------------------------------------

  if (
    esp_now_init() != ESP_OK
  ) {

    Serial.println("ESP-NOW FAILED!");

    stopMotors();

    while (true) {
      delay(1000);
    }
  }

  // Register receive function

  esp_now_register_recv_cb(
    onDataReceive
  );

  Serial.println("ESP-NOW READY");
  Serial.println("Waiting for controller...");

  lastCommandTime = millis();
}

// =====================================================
// MAIN LOOP
// =====================================================

void loop() {

  // ---------------------------------------------------
  // COMMUNICATION SAFETY
  // ---------------------------------------------------

  if (
    controllerFound &&
    millis() - lastCommandTime >
    COMMUNICATION_TIMEOUT
  ) {

    stopMotors();

    controllerFound = false;

    Serial.println();
    Serial.println("CONTROLLER LOST - STOPPING");
    Serial.println("Waiting for controller...");
  }

  delay(10);
}
